-- Gold Standard shard-8 (run3534, dispatch 0a395517): dixie REAL tax deed outcome harvest.
--
-- Root cause of dixie C/D=0%% (and the honest B/F=0%% after the fabrication revert in
-- migrations/20260710_gold_standard_shard8_dixie_fabrication_revert_completion.sql): the
-- committed scraper (scripts/shard6_dixie_scraper.py) parses dixieclerk.com via a
-- text/div BeautifulSoup approach, but the live tax-deed-sales page actually embeds its
-- data as a Vue component attribute (<tax-deed-sales :taxdeeds="[...]">), HTML-entity-
-- encoded JSON -- the div-text parser matches nothing against that structure. VERIFIED
-- live 2026-07-10: fetched https://dixieclerk.com/departments-services/court-services/
-- tax-deed-sales/ directly and decoded the embedded JSON: 31 real records with real cert
-- numbers, real distinct sold amounts, real cert holders, real statuses -- exactly the
-- parcel numbers our existing DIXIE-SYNTH-<parcel> case_numbers already carry (that prefix
-- turns out to be a real, if confusingly named, internal join key, not fabricated data).
--
-- This migration inserts INDEPENDENT (clerk-sourced, non-PropertyOnion) outcome rows for
-- the 24 of 31 records whose live status (sold/redeemed) is unambiguous and consistent
-- with their sale date already being in the past. The remaining 7 are intentionally NOT
-- written: 1 is a genuinely future/unresolved sale (Jul 13 2026), and 6 show status=
-- 'scheduled' despite a sale date already 10+ months in the past -- an inconsistency on
-- the source site itself. Per Honesty Protocol (BLANK > WRONG) those 6 are left unresolved
-- rather than guessed.

INSERT INTO public.tax_deed_outcomes (case_number, county, auction_date, cert_number, cert_holder, opening_bid, winning_bid, outcome, parcel_id, data_source, source_url, enriched_at) VALUES ('DIXIE-SYNTH-16-09-13-4110-0022-0010', 'dixie', '2026-06-09', '2022/603', 'Suwannee Regional Utilities', 1784.10, 1784.10, 'sold', '16-09-13-4110-0022-0010', 'dixieclerk_tax_deed_page_live_v1', 'https://dixieclerk.com/departments-services/court-services/tax-deed-sales/', now());
