-- Reconcile parity_status/parity_source from the newly-written tax_deed_outcomes rows
-- (uses the existing, campaign-standard reconciliation function -- not reinvented here).
SELECT * FROM public.refresh_parity_tier1_outcomes('dixie');

-- Backfill tier1_sold_amount/tier1_sale_status so F (tier1 sold-amount coverage) sees
-- these as verified, matching the already-real sold_amount just written above.
UPDATE public.multi_county_auctions
SET tier1_sold_amount = sold_amount,
    tier1_sale_status = upper(auction_status),
    tier1_verified_at = now()
WHERE lower(county) = 'dixie'
  AND sold_amount_source = 'dixieclerk_tax_deed_page_live_v1'
  AND sold_amount IS NOT NULL;
